import React from 'react';
import { graphql, Link, Navigate } from 'gatsby';
import kebabCase from 'lodash/kebabCase';
import PropTypes from 'prop-types';
import { Helmet } from 'react-helmet';
import styled from 'styled-components';
import { Layout } from '@components';

const StyledPostContainer = styled.main`
  max-width: 1000px;
`;
const StyledPostHeader = styled.header`
  margin-bottom: 50px;
  .tag {
    margin-right: 10px;
  }
`;
const StyledPostContent = styled.div`
  margin-bottom: 100px;
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    margin: 2em 0 1em;
  }

  p {
    margin: 1em 0;
    line-height: 1.5;
    color: var(--light-slate);
  }

  a {
    ${({ theme }) => theme.mixins.inlineLink};
  }

  code {
    background-color: var(--lightest-navy);
    color: var(--lightest-slate);
    border-radius: var(--border-radius);
    font-size: var(--fz-sm);
    padding: 0.2em 0.4em;
  }

  pre code {
    background-color: transparent;
    padding: 0;
  }
`;

class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error('Post Template Error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <Layout location={this.props.location}>
          <StyledPostContainer>
            <h1>Something went wrong</h1>
            <Link to="/pensieve">Back to safety</Link>
          </StyledPostContainer>
        </Layout>
      );
    }
    return this.props.children;
  }
}

const PostTemplate = ({ data, location }) => {
  // Null check for missing data
  if (!data?.markdownRemark) {
    return (
      <Layout location={location}>
        <Helmet title="Post Not Found" />
        <StyledPostContainer>
          <h1>Post Not Found</h1>
          <Link to="/pensieve">Back to all posts</Link>
        </StyledPostContainer>
      </Layout>
    );
  }

  const { frontmatter, html } = data.markdownRemark;
  const { title, date, tags = [] } = frontmatter;

  // Fallback for invalid dates
  const postDate = date ? new Date(date) : new Date();

  return (
    <Layout location={location}>
      <Helmet title={title} />

      <StyledPostContainer>
        <span className="breadcrumb">
          <span className="arrow">&larr;</span>
          <Link to="/pensieve">All memories</Link>
        </span>

        <StyledPostHeader>
          <h1 className="medium-heading">{title}</h1>
          <p className="subtitle">
            <time>
              {postDate.toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'long',
                day: 'numeric',
              })}
            </time>
            {tags.length > 0 && (
              <>
                <span>&nbsp;&mdash;&nbsp;</span>
                {tags.map((tag, i) => (
                  <Link key={i} to={`/pensieve/tags/${kebabCase(tag)}/`} className="tag">
                    #{tag}
                  </Link>
                ))}
              </>
            )}
          </p>
        </StyledPostHeader>

        {html && (
          <StyledPostContent
            dangerouslySetInnerHTML={{ __html: html }}
            onError={() => window.location.reload()} // Auto-reload on content error
          />
        )}
      </StyledPostContainer>
    </Layout>
  );
};

PostTemplate.propTypes = {
  data: PropTypes.shape({
    markdownRemark: PropTypes.shape({
      frontmatter: PropTypes.shape({
        title: PropTypes.string.isRequired,
        date: PropTypes.string,
        slug: PropTypes.string.isRequired,
        tags: PropTypes.arrayOf(PropTypes.string),
      }).isRequired,
      html: PropTypes.string.isRequired,
    }),
  }),
  location: PropTypes.object.isRequired,
};

export default function SafePostTemplate(props) {
  return (
    <ErrorBoundary location={props.location}>
      <PostTemplate {...props} />
    </ErrorBoundary>
  );
}

export const pageQuery = graphql`
  query ($slug: String!) {
    markdownRemark(frontmatter: { slug: { eq: $slug } }) {
      html
      frontmatter {
        title
        description
        date
        slug
        tags
      }
    }
  }
`;
